let readingPages={};try{const saved=JSON.parse(localStorage.getItem('reading-pages-v1'));if(saved&&typeof saved==='object'&&!Array.isArray(saved))readingPages=Object.fromEntries(Object.entries(saved).filter(([,v])=>Number.isInteger(v)&&v>=0));}catch{}
let readingKey='',readingSet=[],readingFinish='',readingTarget=null;
function saveReadingPages(){try{localStorage.setItem('reading-pages-v1',JSON.stringify(readingPages));}catch{toast('本页位置无法保存；课程练习记录仍按原流程保存。');}}
function chunks(text,n=3){const rows=String(text||'').match(/[^。！？]+[。！？]?/g)||[];const out=[];for(let i=0;i<rows.length;i+=n)out.push(rows.slice(i,i+n).join(''));return out;}
const embeddedCommands={pwd:[['先确认位置','pwd','查看执行命令时的当前位置，不会移动目录。'],['进入目录后读回','cd /etc → 再执行 pwd','cd 与 pwd 分工不同：一个改变位置，一个观察位置。']],ls:[['列名字','ls','查看当前目录内容；隐藏名字通常需要 -a。'],['再看详细信息','ls -l','-l 是小写 L，查看权限和属主等信息；不是数字 1。']],cat:[['读一个小文件','cat /home/student/notes.txt','对象是文件路径。先读取，再决定是否需要筛选。']],grep:[['直接查文件','grep -F ERROR /opt/order/logs/app.log','改写自 tldr 字面匹配用法：-F 不解释正则，ERROR 是要找的文本。'],['带行号读证据','grep -F -n r-101 /opt/order/logs/app.log','-n 标记原行号；固定请求标识适合字面匹配。']],head:[['限制开头行数','head -n 2 /opt/order/logs/app.log','-n 后的 2 是数值参数，最后是文件路径。']],tail:[['限制末尾行数','tail -n 2 /opt/order/logs/app.log','先读最近窗口；该示例读快照，不持续跟踪。']],wc:[['数完整文件','wc -l /opt/order/logs/app.log','-l 是小写字母 L。示例日志每行以换行结束。'],['数筛选结果','grep -F ERROR /opt/order/logs/app.log | wc -l','这是学会两条单命令之后的组合例子。']],sort:[['先把相同行排到一起','sort','本模拟从管道接收文本。排序不等于删除重复行。']],uniq:[['合并相邻重复','uniq -c','常先 sort，再用 -c 显示相邻重复计数。']],git:[['观察工作区','git status','先看哪些文件改了；提交、推送和上线是不同动作。'],['检查实际差异','git diff','不是看到文件名就算检查过，要读具体变更。']],jq:[['按键读数据','jq .status health.json','按 JSON 字段结构读取；这个示例是阅读用，不在有限终端执行。']]};
function courseCommands(c){const text=JSON.stringify(c.examples||[])+JSON.stringify(c.steps||[]);return Object.keys(embeddedCommands).filter(cmd=>new RegExp('(?:^|[\\s"\\n|])'+cmd+'(?:\\s|"|$)').test(text));}
function embeddedReferencePages(c){return courseCommands(c).slice(0,3).map(cmd=>P(cmd+'：把开源用法放进本课场景',embeddedCommands[cmd].map(([name,code,explanation])=>name+'：'+explanation),embeddedCommands[cmd].map(([name,code])=>name+'\n'+code).join('\n\n')));}
function sourceNotes(c){const references=[],courseSource=Array.isArray(c.source)?c.source:typeof c.source==='string'?sources[c.source]:null;if(courseSource?.[0]?.includes('Bash'))references.push(['Pure Bash Bible','https://github.com/dylanaraps/pure-bash-bible','补充进阶阅读；课堂先掌握参数、变量、引号和循环，未复制书籍正文。']);if(courseCommands(c).length)references.push(['tldr-pages team and contributors','https://github.com/tldr-pages/tldr','参考其命令用法，改写为本站教学文件和中文解释。CC BY 4.0；原文、固定版本与许可保留在缓存中。']);if(courseSource?.[1]&&!courseSource[1].startsWith('#'))references.push([courseSource[0],courseSource[1],'补充来源；课堂讲解和任务为本站原创，版本差异以原文为准。']);if(hubSubject==='ops')references.push(['DevOps Exercises','https://github.com/bregman-arie/devops-exercises','借鉴主题范围；未复制其题库。']);if(hubSubject==='python')references.push(['Python 官方中文教程','https://docs.python.org/zh-cn/3/tutorial/','语言语法参考；示例、任务与检查条件为本站原创。']);return `<details class="course-endnotes"><summary>课程致谢与项目地址</summary>${references.length?references.map(([name,url,note])=>`<p><a href="${url}" target="_blank" rel="noopener noreferrer">${esc(name)}</a><br>${esc(note)}</p>`).join(''):'<p>本课讲解、图示和题目为本站原创。</p>'}${courseCommands(c).length?'<p><a href="data/tldr/NOTICE.md" target="_blank">tldr 完整署名</a> · <a href="data/tldr/LICENSE.md" target="_blank">许可</a></p>':''}</details>`;}
function termsPages(text){const words=relevantTerms(text).filter(t=>t.length>1).slice(0,15),out=[];for(let i=0;i<words.length;i+=3)out.push({title:'先把词讲清楚'+(words.length>3?' · '+(i/3+1):''),paragraphs:[],terms:words.slice(i,i+3),termsOpen:true});return out;}
function hubTeachingPages(c){if(c.teachingPages)return [...c.teachingPages,...embeddedReferencePages(c)];const pages=[P('这一课要解决什么问题',[c.summary])];pages.push(...termsPages(c.body.join(' ')+c.related));c.body.forEach((text,j)=>chunks(text).forEach((p,k)=>pages.push(P(j?'把判断方法讲清楚':'一步一步理解',[p]))));if(c.diagram&&simpleDiagram(c.diagram))pages.push(P('把关系画出来',['图表示各部分的职责。先找到起点、下一步和返回结果；实际流程仍要结合环境与证据验证。'],'',c.diagram));c.examples.forEach((e,i)=>pages.push(P('读一个完整例子'+(c.examples.length>1?' · '+(i+1):''),[e.meaning],e.text)));pages.push(...embeddedReferencePages(c));pages.push(P('用什么判断自己理解了？',[c.related,'下一步完成练习，再答小测。答错会留在本关；答对也需要你手动继续。']));return pages;}
function baseTeachingPages(c){if(c.teachingPages)return [...c.teachingPages,...embeddedReferencePages(c)];return [P('这条命令用来解决什么问题',[c.scene,c.summary]),...termsPages(c.concept),...chunks(c.concept).map((t,i)=>P('把原理拆开'+(i?' · '+(i+1):''),[t])),...c.steps.map((s,i)=>P('第 '+(i+1)+' 个操作：先读懂',[s.explain],s.cmd)),...embeddedReferencePages(c),P('操作前再提醒',[c.note])];}
function pythonTeachingPages(c){if(c.teachingPages)return c.teachingPages;return [P('什么时候会用到？',[c.why,c.goal]),...termsPages(c.explain),...chunks(c.explain).map(t=>P('把语法讲清楚',[t])),P('先读一段完整代码',['这里是示例代码；下一页逐行解释，不要求现在直接照抄任务。'],c.example),...c.lines.map((line,i)=>P('逐行理解 · '+(i+1),[line],c.example.split('\n')[Math.min(i,c.example.split('\n').length-1)]||'')),P('把例子迁移到本课任务',[c.task,'示例与任务数据不同。运行、观察、修改、验证，再确认；不是只复制打印结果。'])];}
function pageContentHTML(p){return `<h2>${esc(p.title)}</h2>${(p.paragraphs||[]).filter(Boolean).map(x=>`<p>${esc(x)}</p>`).join('')}${p.diagram?simpleDiagram(p.diagram):''}${p.example?`<pre class="page-example ${/^(student|root)@/m.test(p.example)?'terminal-page-example':''}">${p.example.split('\n').map(line=>{const m=line.match(/^((?:student|root)@[^$#]*[$#] )?(.*)$/);return commandInfo[m?.[2]?.split(/\s+/)[0]]?(m[1]?esc(m[1]):'')+annotatedCommand(m[2]):esc(line);}).join('\n')}</pre>`:''}${p.terms?.length?`<div class="page-terms ${p.termsOpen?'definitions':'compact'}">${p.terms.filter(w=>beginnerTerms[w]).map(w=>p.termsOpen?`<h3>${esc(w)}</h3><p>${esc(beginnerTerms[w])}</p>`:`<button type="button" class="explain-token" data-tip="${esc(beginnerTerms[w])}">${esc(w)}</button>`).join('')}</div>`:''}`;}
function paintReading(){if(!readingTarget)return;const index=Math.max(0,Math.min(readingPages[readingKey]||0,readingSet.length-1));readingPages[readingKey]=index;const last=index===readingSet.length-1;readingTarget.innerHTML=`<div class="reading-page-top"><span>讲解 ${index+1}/${readingSet.length} 页</span><span>每页一个主题 · 不会自动翻页</span></div><div class="reading-sheet">${pageContentHTML(readingSet[index])}${last?readingFinish:''}</div><nav class="reading-pager" aria-label="讲解翻页"><button type="button" data-reading="previous" ${index?'':'disabled'}>上一页</button><span>${index+1} / ${readingSet.length}</span><button type="button" data-reading="next" ${last?'disabled':''}>下一页：${esc(readingSet[index+1]?.title||'讲解已读完')}</button></nav>`;decorateTerms();}
function setReading(target,key,pages,finish){readingTarget=target;readingKey=key;readingSet=pages;readingFinish=finish;paintReading();}
function teachingHint(c,task){if(c.reminder)return c.reminder;if(task?.type==='command')return '先确认命令名、选项大小写、操作对象和需要观察的结果。补全只帮你输入，不会自动执行。';if(hubSubject==='network')return '先分清设备的职责，再看地址和请求所处的阶段。一个指示灯或一个结果不能代表全链路成功。';if(hubSubject==='japanese')return '先看字形与语法在当前句子的作用，再对照例子；不按中文读音或逐字翻译猜答案。';if(hubSubject==='agent')return '分清计划、工具实际执行和验证结果。先判断权限与证据，再判断是否完成。';if(hubSubject==='writing')return '先分清原文事实、自己的解释与尚未确认的问题；判断要有文本依据。';return '先用自己的话解释概念，再对照例子判断；不要只凭一个关键词猜答案。';}
function transferExample(c){if(c.transfer)return c.transfer;const cmd=c.tasks?.find(t=>t.command)?.command||c.steps?.[0]?.cmd;if(cmd?.startsWith('whoami'))return '换个账号：whoami 输出 analyst，说明当前有效用户名是 analyst；不代表主机也叫 analyst，更不代表已经是 root。';if(cmd?.startsWith('pwd'))return '换个目录：pwd 输出 /etc，表示当前目录在 /etc。用户家目录仍可能是 /home/student，两者不是同一个概念。';if(cmd?.includes('grep'))return '换一种错误：grep -F WARN service.log 按字面找 WARN；grep -Fi warn service.log 忽略大小写。要数匹配行，可接 wc -l。先核对文件与匹配范围。';if(hubSubject==='network')return '换个现象：Wi-Fi 已连接，但网页打不开。只证明无线接入的一部分；继续核对 IP、网关、DNS 和网站响应，不能直接宣布业务正常。';if(hubSubject==='agent')return '换个任务：模型说“已备份”，但没有工具执行记录和恢复验证。这仍是未验证的结论，应取得实际证据再报告。';if(hubSubject==='writing')return '换个句子：“他关上了门。”事实是关门；“他生气了”是推断，需要前后文证据。记录时把这两层分开。';if(hubSubject==='japanese')return c.examples?.[0]?.text+'\n再次指出本课学到的字形、读音或句子关系，然后换一个词试用。';return c.example||c.examples?.[0]?.text||c.steps?.[0]?.cmd||c.explain||c.related;}
function addQuestionFeedback(){const main=document.querySelector('main');if(!main)return;let c,task,passed,phase,fieldset;if(view==='hub-course'){c=activeHubLesson();task=c.tasks[hubAttempt.step];passed=hubPhase==='quiz'?hubPassed():hubAttempt.verified;phase=hubPhase;fieldset=main.querySelector('fieldset');}else if(view==='classroom'){c=current();passed=learningTab==='quiz'?!!session.quiz&&session.selected===c.answer&&session.step===c.steps.length:!!session.verified;phase=learningTab;fieldset=main.querySelector('.quiz-options')||main.querySelector('fieldset');}else if(view==='python-course'){c=pythonCurrent();passed=pythonPassed(pythonIndex);phase=pythonAttempt().phase;fieldset=main.querySelector('fieldset');}else return;if(!['practice','quiz'].includes(phase))return;const target=fieldset||main.querySelector('#hub-form')||main.querySelector('#command-form');if(target&&!main.querySelector('.before-answer')){const hint=document.createElement('p');hint.className='before-answer';hint.textContent='作答前提醒：'+teachingHint(c,task);target.before(hint);}if(passed&&!main.querySelector('.after-answer')){const box=document.createElement('section');box.className='after-answer';box.innerHTML=`<h3>答对后，再看一个例子</h3><pre>${esc(transferExample(c))}</pre><p>先说清楚为什么，再手动继续；这个例子不会替你执行新的操作。</p>`;const feedback=main.querySelector('.gate-result,.bench-step-gate');if(feedback)feedback.after(box);else main.append(box);if(phase==='quiz'){const note=document.createElement('div');note.innerHTML=sourceNotes(c);box.after(note);}}}
let routePage={};function routeKey(){return view==='roadmap'?'base-roadmap':hubSubject+':'+hubLevel;}
function paginateRoute(){if(view==='roadmap'){const main=document.querySelector('main'),cards=[...main.querySelectorAll('.level-path li')],key=routeKey(),size=window.innerWidth<650?3:6,count=Math.ceil(cards.length/size),page=Math.min(routePage[key]||0,count-1);cards.forEach((card,i)=>card.hidden=i<page*size||i>=(page+1)*size);main.querySelectorAll('.road-card').forEach(card=>card.hidden=![...card.querySelectorAll('.level-path li')].some(li=>!li.hidden));main.querySelector('.journey-art')?.remove();const nav=document.createElement('nav');nav.className='route-pager';nav.innerHTML=`<button data-route-page="-1" ${page?'':'disabled'}>上一页课程</button><span>第 ${page+1}/${count} 页 · ${cards.length} 课</span><button data-route-page="1" ${page===count-1?'disabled':''}>下一页课程</button>`;main.querySelector('.road-grid').before(nav);main.append(nav.cloneNode(true));return;}if(!['subject','python-roadmap'].includes(view))return;const main=document.querySelector('main'),cards=[...main.querySelectorAll('.path-card')];if(!cards.length)return;const key=routeKey(),perPage=window.innerWidth<650?2:4,count=Math.ceil(cards.length/perPage);let page=Math.max(0,Math.min(routePage[key]||0,count-1));const controls=document.createElement('nav');controls.className='route-pager';controls.setAttribute('aria-label','课程列表翻页');controls.innerHTML=`<button type="button" data-route-page="-1" ${page?'':'disabled'}>上一页课程</button><span>第 ${page+1}/${count} 页 · 共 ${cards.length} 课</span><button type="button" data-route-page="1" ${page===count-1?'disabled':''}>下一页课程</button>`;cards.forEach((card,i)=>card.hidden=i<page*perPage||i>=(page+1)*perPage);main.querySelectorAll('.section:has(.path-list)').forEach(section=>{section.hidden=![...section.querySelectorAll('.path-card')].some(c=>!c.hidden);});const list=main.querySelector('.path-card:not([hidden])')?.closest('.path-list')||main.querySelector('.path-list');list.before(controls);const bottom=controls.cloneNode(true);bottom.classList.add('bottom');main.append(bottom);}
function adaptClassroomPages(){readingTarget=null;if(['hub-course','python-course','classroom'].includes(view)){const bar=document.querySelector('.subject-bar');if(bar){const wrap=document.createElement('details');wrap.className='classroom-switcher';const summary=document.createElement('summary');summary.textContent='正在学习：'+(hubSubjects[hubSubject]?.name||'运维')+' · 切换课堂';bar.before(wrap);wrap.append(summary,bar);}}if(view==='hub-course'&&hubPhase==='learn'){const c=activeHubLesson(),article=document.querySelector('.lesson-text');document.querySelector('.lesson-companion')?.remove();document.querySelector('.hub-lesson-grid')?.classList.add('paged-lesson-grid');setReading(article,'hub:'+hubTrack+':'+c.id,hubTeachingPages(c),sourceNotes(c)+'<button class="primary" data-hub="read">讲解读完了，开始练习</button>');}else if(view==='python-course'&&pythonAttempt().phase==='learn'){const c=pythonCurrent(),section=document.querySelector('.python-main>.section');setReading(section,'python:'+c.id,pythonTeachingPages(c),sourceNotes(c)+'<button class="primary" data-python="read">讲解读完了，开始写代码</button>');}else if(view==='classroom'&&learningTab==='learn'){const c=current(),article=document.querySelector('#lesson-panel');document.querySelector('.classroom')?.classList.add('paged-base');document.querySelector('.classroom .journey-art')?.remove();document.querySelector('.classroom>.lesson-companion')?.remove();document.querySelectorAll('.classroom .teaching-picture,.classroom .glossary').forEach(node=>{if(!article?.contains(node))node.remove();});if(article)setReading(article,'base:'+c.id,baseTeachingPages(c),sourceNotes(c)+'<button class="primary" data-action="read-done">讲解读完了，开始练习</button>');}addQuestionFeedback();paginateRoute();}
const depthHubPages=hubTeachingPages,depthBasePages=baseTeachingPages,depthPythonPages=pythonTeachingPages;
hubTeachingPages=c=>[...depthHubPages(c),...(c.depthPages||[])];
baseTeachingPages=c=>[...depthBasePages(c),...(c.depthPages||[])];
pythonTeachingPages=c=>[...depthPythonPages(c),...(c.depthPages||[])];
const pagedBaseRender=render,pagedBaseNav=hubNav;
hubNav=function(){return pagedBaseNav().replace(/<button data-resources="open"[^>]*>[\s\S]*?<\/button>/,'');};
const pagedBaseHome=hubHome;
hubHome=function(){return pagedBaseHome().replace('如果基础已经熟悉，可进入工作实战，从管道、页面请求一路查到 DM8。','运维路线也从常用单条命令起步：先理解参数和路径，再筛选、统计、组合管道，最后沿页面请求查到 DM8。').replace('查看运维工作实战','常用命令 → 工作实战').replace('已认识基础概念？进入 Linux','认识了概念？进入 Linux 命令课堂');};
render=function(){pagedBaseRender();adaptClassroomPages();if(readingTarget){const cue=document.querySelector('.flow-cue>span:last-child');if(cue)cue.textContent='下一步：用下方按钮逐页阅读。最后一页点击“讲解读完了”，再进入练习。';}};
document.addEventListener('click',e=>{const page=e.target.closest('[data-reading]');if(page&&!page.disabled){const index=readingPages[readingKey]||0;readingPages[readingKey]=Math.max(0,Math.min(index+(page.dataset.reading==='next'?1:-1),readingSet.length-1));saveReadingPages();paintReading();document.querySelector('.reading-page-top')?.scrollIntoView({block:'start',behavior:'instant'});}const route=e.target.closest('[data-route-page]');if(route&&!route.disabled){const key=routeKey();routePage[key]=Math.max(0,(routePage[key]||0)+Number(route.dataset.routePage));render();document.querySelector('.route-pager')?.scrollIntoView({block:'start',behavior:'instant'});}});
render();
